<div class="saier-block"><div class="saier-back" @click="changePage()">返回</div><div class="planet-title-slot"><slot name="planetTitle"></slot></div><div class="saier-monster-block" :style="getGroundBackground()"><div class="saier-monster" v-for="monster in monsterShowList" :key="monster.id" :style="getMonsterStyle(monster.position)" @click="clickMonster(monster)"><div class="saier-monster-name">{{monster.name}}</div><div class="saier-monster-level">Lv {{monster.level}}</div></div></div><el-select class="scene-select" v-if="sceneList.length&gt;1" style="width: 150px;" v-model="selectedScene" @change="changeScene"><el-option v-for="item in sceneList" :key="item.label" :label="item.label" :value="item.value"></el-option></el-select><el-select class="saier-select" style="width: 150px;" v-model="selectedGround" @change="changeGround"><el-option v-for="item in props.groundList" :key="item.label" :label="item.label" :value="item.value"></el-option></el-select><div class="planet-scene-text-block" @click="isOpen = !isOpen" :style="{'height':isOpen?'auto':'30px','white-space':isOpen?'':'nowrap'}">{{sceneTipText}}</div><div class="planet-tip-block" @click="isShowTip = false" v-if="isShowTip"><div class="planet-tip" @click.stop=""><div class="planet-tip-text">{{clickTipText}}</div><div class="planet-tip-text" v-if="selectMonster.fightMes.lockLevel">注意：该Boss有{{selectMonster.fightMes.lockLevel}} 级等级锁！</div><div class="planet-tip-button" @click="tipClickSure()">确 定</div></div></div></div>